const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const { v4: uuidv4 } = require('uuid');
const path = require('path');
const analytics = require('./analytics');
const CARD_CATEGORIES = require('./card-categories');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

analytics.init();
app.use(express.json({ limit: '16kb' }));

// Ключ для просмотра статистики. Задайте STATS_KEY в окружении на сервере,
// иначе /api/stats будет отдавать 403 и цифры останутся только в файлах.
const STATS_KEY = process.env.STATS_KEY || '';

app.use(express.static(path.join(__dirname, 'public'), {
    etag: false,
    lastModified: false,
    setHeaders: function (res, filePath) {
        if (/\.(js|css|html)$/i.test(filePath)) {
            res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
            res.setHeader('Pragma', 'no-cache');
            res.setHeader('Expires', '0');
        }
    }
}));

// ── Аналитика: приём данных и отчёт ────────────────────────────────────

// Fake door: клик по «Режим преподавателя» и оставленная почта.
// Это и есть замер готовности платить — намного честнее, чем спрашивать
// «а вы бы заплатили?», потому что человек тратит действие, а не мнение.
app.post('/api/lead', (req, res) => {
    const body = req.body || {};
    const email = String(body.email || '').trim().slice(0, 120);
    const role = String(body.role || '').trim().slice(0, 60);
    const comment = String(body.comment || '').trim().slice(0, 500);
    if (!email || email.indexOf('@') === -1) {
        return res.status(400).json({ ok: false, error: 'Нужна почта' });
    }
    analytics.saveLead({ email, role, comment, source: String(body.source || 'welcome').slice(0, 40) });
    res.json({ ok: true });
});

// Точечные клики с фронта. Белый список, чтобы эндпоинт нельзя было
// использовать как помойку для произвольных счётчиков.
const CLIENT_EVENTS = ['fakedoor_click', 'rules_opened', 'solo_opened'];
app.post('/api/event', (req, res) => {
    const name = String((req.body || {}).name || '');
    if (CLIENT_EVENTS.indexOf(name) === -1) return res.status(400).json({ ok: false });
    analytics.bump(name);
    res.json({ ok: true });
});

// Мини-опрос после игры — прямая проверка гипотезы «игра придаёт уверенности».
app.post('/api/survey', (req, res) => {
    const body = req.body || {};
    const confidence = parseInt(body.confidence, 10);
    if (!(confidence >= 1 && confidence <= 10)) {
        return res.status(400).json({ ok: false, error: 'Нужна оценка 1–10' });
    }
    analytics.saveSurvey({
        confidence,
        wasScary: !!body.wasScary,
        firstTime: !!body.firstTime,
        mode: String(body.mode || '').slice(0, 20),
    });
    res.json({ ok: true });
});

// Отчёт. Открывать так: /api/stats?key=ВАШ_КЛЮЧ
app.get('/api/stats', (req, res) => {
    if (!STATS_KEY || req.query.key !== STATS_KEY) {
        return res.status(403).json({ error: 'Нужен правильный ?key=' });
    }
    res.json(analytics.getStats());
});

// REST-эндпоинт для случайных комбинаций на welcome-экране
// Случайный продукт: прилагательное и особенность склоняются по роду предмета
function randomCombo() {
    const itemObj = ITEMS[Math.floor(Math.random() * ITEMS.length)];
    const gender = itemObj.gender;
    const item = itemObj.word;
    const adjective = declineAdjective(ADJECTIVES[Math.floor(Math.random() * ADJECTIVES.length)], gender);
    const feature = declineFeature(FEATURES[Math.floor(Math.random() * FEATURES.length)], gender);
    return {
        text: adjective + ' ' + item + ', ' + feature.toLowerCase(),
        // По частям — для живых карт на главной странице
        adjective: adjective,
        item: item,
        feature: feature,
    };
}

app.get('/api/random-combo', (req, res) => {
    res.json(randomCombo());
});

// Пачка продуктов — для бегущей строки «биржи стартапов» на главной
app.get('/api/random-combos', (req, res) => {
    const n = Math.min(12, Math.max(1, parseInt(req.query.n, 10) || 8));
    const list = [];
    for (let i = 0; i < n; i++) list.push(randomCombo());
    res.json(list);
});

// Категории карт для лобби и одиночного режима
app.get('/api/card-categories', (req, res) => {
    res.json(cardCategoriesCatalog());
});

app.get('/api/solo-cards', (req, res) => {
    var settings = req.query;
    // ?cats={"items":["food","home"]} — какие категории играют
    var cats = {};
    try { cats = normalizeCardCategories(JSON.parse(settings.cats || '{}')); } catch (e) { cats = {}; }
    var useModifier = settings.modifier && settings.modifier !== 'none';
    var modifierType = settings.modifier || 'none';
    var useReviews = settings.useReviews === 'true';
    var pseudoMode = settings.pseudoMode === 'true';
    var useTargetAudience = settings.useTargetAudience === 'true';
    var useHiddenDefects = settings.useHiddenDefects === 'true';
    var usePackaging = settings.usePackaging === 'true';
    var useEvents = settings.useEvents === 'true';

    // Предмет
    var itemObj = ITEMS[randomDeckIndex(cats, 'items')];
    var gender = itemObj.gender;

    // Прилагательное
    var adjRaw = ADJECTIVES[randomDeckIndex(cats, 'adjectives')];
    var adjective = declineAdjective(adjRaw, gender);

    var cards = {
        adjective: adjective,
        item: itemObj.word,
    };

    // Особенность
    if (!pseudoMode) {
        var featRaw = FEATURES[randomDeckIndex(cats, 'features')];
        cards.feature = declineFeature(featRaw, gender);
    }

    // Модификатор
    if (modifierType === 'addition') {
        cards.modifier = ADDITIONS[randomDeckIndex(cats, 'additions')];
    } else if (modifierType === 'metaphor') {
        // Генерируем метафору
        var useFemale = Math.random() < 0.5;
        if (useFemale) {
            var p1f = METAPHOR_PART1_F[Math.floor(Math.random() * METAPHOR_PART1_F.length)];
            var p2f = METAPHOR_PART2_F[Math.floor(Math.random() * METAPHOR_PART2_F.length)];
            cards.modifier = p1f + ' ' + p2f;
        } else {
            var p1m = METAPHOR_PART1_M[Math.floor(Math.random() * METAPHOR_PART1_M.length)];
            var p2m = METAPHOR_PART2_M[Math.floor(Math.random() * METAPHOR_PART2_M.length)];
            cards.modifier = p1m + ' ' + p2m;
        }
    }

    // Отзыв
    if (useReviews) {
        cards.review = REVIEWS[randomDeckIndex(cats, 'reviews')];
    }

    // Целевая аудитория
    if (useTargetAudience) {
        cards.targetAudience = TARGET_AUDIENCE[randomDeckIndex(cats, 'targetAudience')];
    }

    // Скрытый дефект
    if (useHiddenDefects) {
        cards.hiddenDefect = HIDDEN_DEFECTS[randomDeckIndex(cats, 'hiddenDefects')];
    }

    // Упаковка
    if (usePackaging) {
        cards.packaging = PACKAGING[randomDeckIndex(cats, 'packaging')];
    }

    // Событие
    var event = null;
    if (useEvents) {
        event = EVENTS[Math.floor(Math.random() * EVENTS.length)];
    }

    analytics.bump('solo_generated');
    res.json({ cards, event });
});
