server.listen(PORT, () => {
    console.log('');
    console.log('  🚀 ═══════════════════════════════════════════');
    console.log('  🚀  ВПАРИТЬ v2.0');
    console.log('  🚀  Сервер запущен на порту ' + PORT);
    console.log('  🚀  Откройте: http://localhost:' + PORT);
    console.log('  🚀 ═══════════════════════════════════════════');
    console.log('');
});

// =====================================================================
// РЕЖИМ "ГЕНЕРАТОР АБСУРДА" — сбор карт от игроков
// =====================================================================

function getCardInputPhases(room) {
    var phases = ['adjective', 'item'];
    if (!room.settings.pseudoMode) {
        phases.push('feature');
    }
    if (room.settings.useReviews) {
        phases.push('review');
    }
    if (room.settings.useTargetAudience) {
        phases.push('targetAudience');
    }
    if (room.settings.useHiddenDefects) {
        phases.push('hiddenDefect');
    }
    if (room.settings.usePackaging) {
        phases.push('packaging');
    }
    return phases;
}

function startCardInputPhase(room, cardType) {
    room.state = 'cardInput';
    room.currentCardInputType = cardType;

    var mapKeyMap = {
        adjective: 'adjectives',
        item: 'items',
        feature: 'features',
        review: 'reviews',
        targetAudience: 'targetAudience',
        hiddenDefect: 'hiddenDefects',
        packaging: 'packaging',
    };
    var mapKey = mapKeyMap[cardType] || 'adjectives';

    // Инициализируем Map если нет
    if (!room.customCards[mapKey]) room.customCards[mapKey] = new Map();
    room.customCards[mapKey].clear();

    room.players.forEach(p => {
        if (p.eliminated || !p.connected) {
            room.customCards[mapKey].set(p.id, null);
        }
    });

    broadcastToRoom(room, {
        type: 'cardInputPhase',
        cardType: cardType,
        round: room.currentRound,
        totalRounds: room.totalRounds,
        inputTime: room.settings.cardInputTime,
    });

    if (room.customCards[mapKey].size >= room.players.size) {
        processCardInputPhase(room);
        return;
    }

    startTimer(room, room.settings.cardInputTime, () => {
        processCardInputPhase(room);
    });
}

function processCardInputPhase(room) {
    clearTimer(room);

    var cardType = room.currentCardInputType;
    var mapKeyMap = {
        adjective: 'adjectives',
        item: 'items',
        feature: 'features',
        review: 'reviews',
        targetAudience: 'targetAudience',
        hiddenDefect: 'hiddenDefects',
        packaging: 'packaging',
    };
    var mapKey = mapKeyMap[cardType] || 'adjectives';
    var cardMap = room.customCards[mapKey];

    room.players.forEach(p => {
        if (!cardMap.has(p.id)) {
            cardMap.set(p.id, null);
        }
    });

    var phases = getCardInputPhases(room);
    var currentIndex = phases.indexOf(cardType);
    if (currentIndex < phases.length - 1) {
        var nextType = phases[currentIndex + 1];
        startCardInputPhase(room, nextType);
    } else {
        dealCustomCards(room);
    }
}

function dealCustomCards(room) {
    var adjectives = [];
    var items = [];
    var features = [];
    var reviews = [];
    var modifiers = [];

    room.customCards.adjectives.forEach((text) => {
        if (text && text.trim()) {
            adjectives.push(text.trim().toUpperCase());
        } else {
            adjectives.push(ADJECTIVES[drawDeckIndex(room, 'adjectives')]);
        }
    });

    room.customCards.items.forEach((text) => {
        if (text && text.trim()) {
            items.push(text.trim().toUpperCase());
        } else {
            items.push(ITEMS[drawDeckIndex(room, 'items')].word);
        }
    });

    room.customCards.features.forEach((text) => {
        if (text && text.trim()) {
            features.push(text.trim().toUpperCase());
        } else {
            features.push(FEATURES[drawDeckIndex(room, 'features')]);
        }
    });

    if (room.settings.useReviews && room.customCards.reviews) {
        room.customCards.reviews.forEach((text) => {
            if (text && text.trim()) {
                reviews.push(text.trim().toUpperCase());
            } else {
                reviews.push(REVIEWS[drawDeckIndex(room, 'reviews')]);
            }
        });
        reviews = shuffle(reviews);
    }

    var customTargetAudience = [];
    var customHiddenDefects = [];
    var customPackaging = [];

    if (room.settings.useTargetAudience && room.customCards.targetAudience) {
        room.customCards.targetAudience.forEach((text) => {
            if (text && text.trim()) {
                customTargetAudience.push(text.trim().toUpperCase());
            } else {
                customTargetAudience.push(TARGET_AUDIENCE[drawDeckIndex(room, 'targetAudience')]);
            }
        });
        customTargetAudience = shuffle(customTargetAudience);
    }

    if (room.settings.useHiddenDefects && room.customCards.hiddenDefects) {
        room.customCards.hiddenDefects.forEach((text) => {
            if (text && text.trim()) {
                customHiddenDefects.push(text.trim().toUpperCase());
            } else {
                customHiddenDefects.push(HIDDEN_DEFECTS[drawDeckIndex(room, 'hiddenDefects')]);
            }
        });
        customHiddenDefects = shuffle(customHiddenDefects);
    }

    if (room.settings.usePackaging && room.customCards.packaging) {
        room.customCards.packaging.forEach((text) => {
            if (text && text.trim()) {
                customPackaging.push(text.trim().toUpperCase());
            } else {
                customPackaging.push(PACKAGING[drawDeckIndex(room, 'packaging')]);
            }
        });
        customPackaging = shuffle(customPackaging);
    }

    // Модификаторы НЕ кастомные (генератор абсурда отключает модификаторы)
    // Но на всякий случай — если modifier включен, берём из базы
    // (по логике modifier === 'none' при cardSource === 'players')

    adjectives = shuffle(adjectives);
    items = shuffle(items);
    features = shuffle(features);

    var playerIds = [];
    room.players.forEach(p => playerIds.push(p.id));
    playerIds = shuffle(playerIds);

    for (var i = 0; i < playerIds.length; i++) {
        var player = room.players.get(playerIds[i]);
        if (!player) continue;

        player.cards = {
            adjective: adjectives[i % adjectives.length],
            item: items[i % items.length],
        };

        if (!room.settings.pseudoMode) {
            player.cards.feature = features[i % features.length];
        }

        if (room.settings.useReviews && reviews.length > 0) {
            player.cards.review = reviews[i % reviews.length];
        }

        if (room.settings.useTargetAudience && customTargetAudience.length > 0) {
            player.cards.targetAudience = customTargetAudience[i % customTargetAudience.length];
        }

        if (room.settings.useHiddenDefects && customHiddenDefects.length > 0) {
            player.cards.hiddenDefect = customHiddenDefects[i % customHiddenDefects.length];
        }

        if (room.settings.usePackaging && customPackaging.length > 0) {
            player.cards.packaging = customPackaging[i % customPackaging.length];
        }

        player.pitchText = '';
        player.isReady = false;
    }

    room.state = 'preparation';
    sendRoundStartToAll(room);

    startTimer(room, room.settings.prepTime, () => {
        startPresentations(room);
    });
}

function dealCardsFromDatabase(room) {
    room.players.forEach(p => {
        var itemIndex = drawDeckIndex(room, 'items');
        var itemObj = ITEMS[itemIndex];
        var gender = itemObj.gender;
        var itemWord = itemObj.word;

        var adjIndex = drawDeckIndex(room, 'adjectives');
        var adjWord = declineAdjective(ADJECTIVES[adjIndex], gender);

        p.cards = {
            adjective: adjWord,
            item: itemWord,
        };

        // Особенность — только если НЕ псевдоинновации
        if (!room.settings.pseudoMode) {
            var featIndex = drawDeckIndex(room, 'features');
            var featWord = declineFeature(FEATURES[featIndex], gender);
            p.cards.feature = featWord;
        }

        // Модификатор
        if (room.settings.modifier === 'addition') {
            var addIdx = drawDeckIndex(room, 'additions');
            p.cards.modifier = ADDITIONS[addIdx];
        } else if (room.settings.modifier === 'metaphor') {
            p.cards.modifier = generateMetaphor();
        }

        // Отзыв
        if (room.settings.useReviews) {
            var reviewIndex = drawDeckIndex(room, 'reviews');
            p.cards.review = REVIEWS[reviewIndex];
        }

        // Целевая аудитория
        if (room.settings.useTargetAudience) {
            var taIndex = drawDeckIndex(room, 'targetAudience');
            p.cards.targetAudience = TARGET_AUDIENCE[taIndex];
        }

        // Скрытый дефект
        if (room.settings.useHiddenDefects) {
            var hdIndex = drawDeckIndex(room, 'hiddenDefects');
            p.cards.hiddenDefect = HIDDEN_DEFECTS[hdIndex];
        }

        // Упаковка
        if (room.settings.usePackaging) {
            var pkgIndex = drawDeckIndex(room, 'packaging');
            p.cards.packaging = PACKAGING[pkgIndex];
        }

        p.pitchText = '';
        p.isReady = false;
    });
}

function sendRoundStartToAll(room) {
    statsPrepStart(room);
    room.players.forEach(p => {
        sendToPlayer(room, p.id, {
            type: 'roundStart',
            round: room.currentRound,
            totalRounds: room.totalRounds,
            yourCards: p.cards,
            event: room.currentEvent,
            phase: 'preparation',
            players: getPlayersPublicInfo(room),
            presentationOrder: room.presentationOrder.map(id => {
                return { id, nickname: getDisplayNickname(room, id) };
            }),
            prepTime: room.settings.prepTime,
            streamerMode: room.settings.streamerMode,
        });
    });
    sendToSpectators(room, {
        type: 'roundStart',
        round: room.currentRound,
        totalRounds: room.totalRounds,
        yourCards: {},
        event: room.currentEvent,
        phase: 'preparation',
        players: getPlayersPublicInfo(room),
        presentationOrder: room.presentationOrder.map(id => {
            return { id, nickname: getDisplayNickname(room, id) };
        }),
        prepTime: room.settings.prepTime,
        streamerMode: room.settings.streamerMode,
    });
}

function applyBlackSwan(room, presenter) {
    var allKeys = ['adjective', 'item', 'feature', 'modifier', 'review', 'targetAudience', 'hiddenDefect', 'packaging'];
    var availableKeys = [];
    for (var i = 0; i < allKeys.length; i++) {
        if (presenter.cards[allKeys[i]]) {
            availableKeys.push(allKeys[i]);
        }
    }
    if (availableKeys.length === 0) return null;

    var targetKey = availableKeys[Math.floor(Math.random() * availableKeys.length)];
    var oldValue = presenter.cards[targetKey];
    var newValue = null;
    var gender = getGenderOfItem(presenter.cards.item);

    if (targetKey === 'item') {
        var itemIndex = drawDeckIndex(room, 'items');
        newValue = ITEMS[itemIndex].word;
        presenter.cards.item = newValue;
    } else if (targetKey === 'adjective') {
        var adjIdx = drawDeckIndex(room, 'adjectives');
        newValue = declineAdjective(ADJECTIVES[adjIdx], gender);
        presenter.cards.adjective = newValue;
    } else if (targetKey === 'feature') {
        var featIdx = drawDeckIndex(room, 'features');
        newValue = declineFeature(FEATURES[featIdx], gender);
        presenter.cards.feature = newValue;
    } else if (targetKey === 'review') {
        var revIdx = drawDeckIndex(room, 'reviews');
        newValue = REVIEWS[revIdx];
        presenter.cards.review = newValue;
    } else if (targetKey === 'modifier') {
        if (room.settings.modifier === 'addition') {
            var addIdx = drawDeckIndex(room, 'additions');
            newValue = ADDITIONS[addIdx];
        } else if (room.settings.modifier === 'metaphor') {
            newValue = generateMetaphor();
        }
        presenter.cards.modifier = newValue;
    } else if (targetKey === 'targetAudience') {
        var taIdx = drawDeckIndex(room, 'targetAudience');
        newValue = TARGET_AUDIENCE[taIdx];
        presenter.cards.targetAudience = newValue;
    } else if (targetKey === 'hiddenDefect') {
        var hdIdx = drawDeckIndex(room, 'hiddenDefects');
        newValue = HIDDEN_DEFECTS[hdIdx];
        presenter.cards.hiddenDefect = newValue;
    } else if (targetKey === 'packaging') {
        var pkgIdx = drawDeckIndex(room, 'packaging');
        newValue = PACKAGING[pkgIdx];
        presenter.cards.packaging = newValue;
    }

    var labelMap = {
        adjective: 'Прилагательное',
        item: 'Предмет',
        feature: 'Особенность',
        review: 'Первый отзыв',
        modifier: 'Модификатор',
        targetAudience: 'Целевая аудитория',
        hiddenDefect: 'Скрытый дефект',
        packaging: 'Упаковка',
    };

    console.log(`[BLACK SWAN] ${presenter.nickname}: ${targetKey} "${oldValue}" -> "${newValue}"`);

    return {
        cardKey: targetKey,
        oldValue: oldValue,
        newValue: newValue,
        label: labelMap[targetKey] || targetKey,
    };
}

function getGenderOfItem(itemWord) {
    if (!itemWord) return 'm';
    for (var i = 0; i < ITEMS.length; i++) {
        if (ITEMS[i].word === itemWord) return ITEMS[i].gender;
    }
    return 'm';
}

function generateMetaphor() {
    // 50/50 женский или мужской род
    if (Math.random() < 0.5) {
        var p1 = METAPHOR_PART1_F[Math.floor(Math.random() * METAPHOR_PART1_F.length)];
        var p2 = METAPHOR_PART2_F[Math.floor(Math.random() * METAPHOR_PART2_F.length)];
    } else {
        var p1 = METAPHOR_PART1_M[Math.floor(Math.random() * METAPHOR_PART1_M.length)];
        var p2 = METAPHOR_PART2_M[Math.floor(Math.random() * METAPHOR_PART2_M.length)];
    }
    return p1 + ' ' + p2;
}